package org.arn.y2627.pages

import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import com.varabyte.kobweb.core.Page
import kotlinx.browser.window
import kotlinx.coroutines.await
import androidx.compose.runtime.getValue
import androidx.compose.runtime.setValue
import kotlinx.serialization.json.Json
import org.arn.y2627.models.Asset
import org.jetbrains.compose.web.dom.*

@Page("gallery")
@Composable
fun GalleryPage() {
    Div(
        attrs = {
            classes("page")
        }
    ) {
        H1 {
            Text("Galerie")
        }

        GetAssets()
    }
}

@Composable
fun GetAssets() {
    var pictures by remember { mutableStateOf<List<Asset>>(emptyList()) }

    LaunchedEffect(Unit) {
        val response = window.fetch("json/assets.json").await()
        val json = response.text().await()
        pictures = Json.decodeFromString(json)
    }

    for (a in pictures) {
        A (
            attrs = {
                classes("element")
            }
        ) {
            Img (
                src = a.path
            )

            P {
                Text(a.name)
            }
        }
    }
}